        import msvcrt
        ch = msvcrt.getwch()
        if ch in ("\x00", "\xe0"):
            ch = msvcrt.getwch()
            return {"H": "up", "P": "down", "K": "left", "M": "right"}.get(ch)
        return "quit" if ch in ("q", "Q", "\x03") else None
    import termios
    import tty
    fd = sys.stdin.fileno()
    old = termios.tcgetattr(fd)
    try:
        tty.setraw(fd)
        ch = sys.stdin.read(1)
        if ch == "\x1b":
            seq = sys.stdin.read(2)
            if len(seq) == 2:
                return {"A": "up", "B": "down", "C": "right", "D": "left"}.get(seq[1])
            return None
        return "quit" if ch in ("q", "Q", "\x03") else None
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)


def render(game):
    lines = ["\033[2J\033[H2048",
             "Score: {}   Highest tile: {}".format(game.score, game.highest),
             "+" + "------+" * 4]
    for row in game.board:
        cells = []
        for v in row:
            if v:
                cells.append("\033[48;5;{};30m{:>5} \033[0m".format(COLORS.get(v, "37"), v))
            else:
                cells.append("      ")
        lines.append("|" + "|".join(cells) + "|")
        lines.append("+" + "------+" * 4)
    lines.append("Arrow keys: move | q: quit")
    print("\n".join(lines))
